// Generated by OrchestKit Claude Plugin
// Created: 2026-09-14

/**
 * ESM bundles must not contain esbuild's dynamic-require shim (#3892).
 *
 * The hooks ship as `format: 'esm'` bundles. When source code calls a bare
 * `require('node:os')`, esbuild cannot hoist it to an import and instead emits
 * a shim that throws `Dynamic require of "node:os" is not supported` at the
 * moment the call runs. Nothing fails at build time or at bundle import, so
 * the error only appears when the code path executes in production: for
 * `subagent-stop/feedback-loop` that was every SubagentStop.
 *
 * The committed dist/ is release-owned and CI does not rebuild it before
 * vitest, so these tests build the bundles themselves from src/entries rather
 * than trusting whatever dist/ happens to hold.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { build } from 'esbuild';
import { spawnSync } from 'node:child_process';
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync } from 'node:fs';
import { hostname, tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const __dirname = import.meta.dirname ?? dirname(fileURLToPath(import.meta.url));
const HOOKS_DIR = join(__dirname, '..', '..', '..');
const ENTRIES_DIR = join(HOOKS_DIR, 'src', 'entries');
const SHIM_MARKER = 'Dynamic require of';

/** Mirrors commonBuildOptions in esbuild.config.mjs (the parts that shape output). */
const BUILD_OPTIONS = {
  bundle: true,
  format: 'esm' as const,
  platform: 'node' as const,
  target: 'node20',
  minify: false,
  logLevel: 'silent' as const,
};

const entryFiles = readdirSync(ENTRIES_DIR).filter((f) => f.endsWith('.ts'));

describe('ESM hook bundles carry no dynamic-require shim (#3892)', () => {
  it('discovers the entry points', () => {
    expect(entryFiles).toContain('subagent.ts');
    expect(entryFiles.length).toBeGreaterThanOrEqual(10);
  });

  it.each(entryFiles)('%s builds without a bare require()', async (entry) => {
    const result = await build({
      ...BUILD_OPTIONS,
      entryPoints: [join(ENTRIES_DIR, entry)],
      write: false,
      outfile: join(tmpdir(), `ork-shim-check-${entry}.mjs`),
    });
    const text = result.outputFiles.map((f) => f.text).join('\n');
    expect(text, `${entry}: some source file calls require() directly; use an ESM import (or createRequire for an intentionally lazy load)`).not.toContain(SHIM_MARKER);
  }, 30_000);
});

describe('subagent-stop/feedback-loop runs from the built bundle (#3892)', () => {
  let work: string;
  let bundle: string;

  beforeAll(async () => {
    work = mkdtempSync(join(tmpdir(), 'ork-3892-bundle-'));
    bundle = join(work, 'subagent.mjs');
    await build({ ...BUILD_OPTIONS, entryPoints: [join(ENTRIES_DIR, 'subagent.ts')], outfile: bundle });
  }, 30_000);

  afterAll(() => {
    rmSync(work, { recursive: true, force: true });
  });

  it('writes the decision log instead of throwing on the instance id', () => {
    const project = join(work, 'project');
    const driver = `
      const mod = await import(${JSON.stringify(pathToFileURL(bundle).href)});
      const hook = mod.getHook('subagent-stop/feedback-loop');
      const result = hook({
        session_id: 'bundle-test-session',
        hook_event_name: 'SubagentStop',
        agent_type: 'ork:test-generator',
        agent_output: 'All tests written.',
      });
      process.stdout.write(JSON.stringify(result));
    `;
    const env: NodeJS.ProcessEnv = {
      ...process.env,
      CLAUDE_PROJECT_DIR: project,
      CLAUDE_SESSION_ID: 'bundle-test-session',
      ORCHESTKIT_LOG_LEVEL: 'error',
    };
    // Each of these short-circuits before the throwing line, which is how the
    // bug hid from the dispatcher e2e test on machines with agent teams on.
    delete env.CLAUDE_INSTANCE_ID;
    delete env.CLAUDE_CODE_TEAM_NAME;
    delete env.CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS;

    const run = spawnSync(process.execPath, ['--input-type=module', '-e', driver], {
      env,
      encoding: 'utf8',
      timeout: 20_000,
    });

    expect(run.stderr).not.toContain(SHIM_MARKER);
    expect(run.status, run.stderr).toBe(0);
    const result = JSON.parse(run.stdout) as { continue: boolean; systemMessage?: string };
    expect(result.continue).toBe(true);
    expect(result.systemMessage ?? '').not.toContain('Hook error');

    const logPath = join(project, '.claude', 'coordination', 'decision-log.json');
    expect(existsSync(logPath)).toBe(true);
    const log = JSON.parse(readFileSync(logPath, 'utf8')) as {
      decisions: Array<{ made_by: { instance_id: string; agent_type: string } }>;
    };
    expect(log.decisions).toHaveLength(1);
    expect(log.decisions[0].made_by.agent_type).toBe('test-generator');
    expect(log.decisions[0].made_by.instance_id).toMatch(new RegExp(`^${hostname().replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}-\\d+$`));
  }, 30_000);
});
